import functools
import inspect
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

def my_dependency(a: int, b: str):
    return f"{a} {b}"

partial_dep = functools.partial(my_dependency, a=1)

print(f"Original signature: {inspect.signature(my_dependency)}")
print(f"Partial signature: {inspect.signature(partial_dep)}")

try:
    sig = get_typed_signature(partial_dep)
    print(f"Typed signature: {sig}")
except Exception as e:
    print(f"Error getting typed signature: {e}")

def my_async_dependency(a: int, b: str):
    return f"{a} {b}"

async def my_async_dependency_async(a: int, b: str):
    return f"{a} {b}"

partial_async_dep = functools.partial(my_async_dependency_async, a=1)
try:
    sig = get_typed_signature(partial_async_dep)
    print(f"Typed async signature: {sig}")
except Exception as e:
    print(f"Error getting typed async signature: {e}")

class MyCallableClass:
    def __call__(self, a: int, b: str):
        return f"{a} {b}"

callable_class = MyCallableClass()
partial_callable_class = functools.partial(callable_class, a=1)
try:
    sig = get_typed_signature(partial_callable_class)
    print(f"Typed callable class signature: {sig}")
except Exception as e:
    print(f"Error getting typed callable class signature: {e}")

